INT_MIN, INT_MAX = -2**31, 2**31 - 1


def my_atoi(s: str) -> int:
    i, n = 0, len(s)
    while i < n and s[i] == " ":
        i += 1
    sign = 1
    if i < n and s[i] in "+-":
        sign = -1 if s[i] == "-" else 1
        i += 1
    total = 0
    while i < n and s[i].isdigit():
        total = total * 10 + int(s[i])
        if sign == 1 and total > INT_MAX:
            return INT_MAX
        if sign == -1 and -total < INT_MIN:
            return INT_MIN
        i += 1
    return sign * total
